// Same Rust source for native and Wasm, wrapping word operations.
#[no_mangle]pub extern "C" fn bench_alloc(n:usize)->*mut u32{let mut v=vec![0;n];let p=v.as_mut_ptr();std::mem::forget(v);p}
#[no_mangle]pub unsafe extern "C" fn bench_free(p:*mut u32,n:usize){drop(Vec::from_raw_parts(p,n,n));}
#[no_mangle]pub unsafe extern "C" fn bench_eval(case:u32,xp:*const u32,xn:usize,yp:*const u32,yn:usize,seed:u32,k:u32,out:*mut u32)->usize{let xs=std::slice::from_raw_parts(xp,xn);let _ys=std::slice::from_raw_parts(yp,yn);match case{
0=>{let positive:Vec<u32>=xs.iter().copied().filter(|&x|(x<seed)).collect();let mapped:Vec<u32>=positive.iter().map(|&x|((x).wrapping_add(7u32)).wrapping_mul((x).wrapping_add(seed))).collect();let mut a=0u32;for x in mapped{a=a.wrapping_add(x);}let negative:Vec<u32>=xs.iter().copied().filter(|&x|!(x<seed)).collect();let mapped:Vec<u32>=negative.iter().map(|&x|((x).wrapping_add(7u32)).wrapping_mul((x).wrapping_add(seed))).collect();let mut b=0u32;for x in mapped{b=b.wrapping_add(x);}*out=a.wrapping_add(b);1},
1=>{let positive:Vec<u32>=xs.iter().copied().filter(|&x|(x<seed)).collect();let mapped:Vec<u32>=positive.iter().map(|&x|((x).wrapping_add(7u32)).wrapping_mul((x).wrapping_add(seed))).collect();let mut a=0u32;for x in mapped{a=a.wrapping_add(x);}let negative:Vec<u32>=xs.iter().copied().filter(|&x|!(x<seed)).collect();let mapped:Vec<u32>=negative.iter().map(|&x|((x).wrapping_add(7u32)).wrapping_mul((x).wrapping_add(seed))).collect();let mut b=0u32;for x in mapped{b=b.wrapping_add(x);}*out=a.wrapping_sub(b);1},
2=>{let positive:Vec<u32>=xs.iter().copied().filter(|&x|(x<seed)).collect();let mapped:Vec<u32>=positive.iter().map(|&x|((x).wrapping_add(7u32)).wrapping_mul((x).wrapping_add(seed))).collect();let mut a=0u32;for x in mapped{a=a.wrapping_add(x);}let negative:Vec<u32>=xs.iter().copied().filter(|&x|!(x<seed)).collect();let mapped:Vec<u32>=negative.iter().map(|&x|((x).wrapping_add(7u32)).wrapping_mul((x).wrapping_add(seed))).collect();let mut b=0u32;for x in mapped{b=b.wrapping_add(x);}*out=a.wrapping_mul(k).wrapping_add(b.wrapping_mul(3));1},
3=>{let positive:Vec<u32>=xs.iter().copied().filter(|&x|(x>seed)).collect();let mapped:Vec<u32>=positive.iter().map(|&x|((if (x<k){(k).wrapping_sub(x)}else{(x).wrapping_sub(k)})).wrapping_add(seed)).collect();let mut a=0u32;for x in mapped{a=a.wrapping_add(x);}let negative:Vec<u32>=xs.iter().copied().filter(|&x|!(x>seed)).collect();let mapped:Vec<u32>=negative.iter().map(|&x|((if (x<k){(k).wrapping_sub(x)}else{(x).wrapping_sub(k)})).wrapping_add(seed)).collect();let mut b=0u32;for x in mapped{b=b.wrapping_add(x);}*out=a.wrapping_add(b);1},
4=>{let positive:Vec<u32>=xs.iter().copied().filter(|&x|(x>seed)).collect();let mapped:Vec<u32>=positive.iter().map(|&x|((if (x<k){(k).wrapping_sub(x)}else{(x).wrapping_sub(k)})).wrapping_add(seed)).collect();let mut a=0u32;for x in mapped{a=a.wrapping_add(x);}let negative:Vec<u32>=xs.iter().copied().filter(|&x|!(x>seed)).collect();let mapped:Vec<u32>=negative.iter().map(|&x|((if (x<k){(k).wrapping_sub(x)}else{(x).wrapping_sub(k)})).wrapping_add(seed)).collect();let mut b=0u32;for x in mapped{b=b.wrapping_add(x);}*out=a.wrapping_sub(b);1},
5=>{let positive:Vec<u32>=xs.iter().copied().filter(|&x|(x>seed)).collect();let mapped:Vec<u32>=positive.iter().map(|&x|((if (x<k){(k).wrapping_sub(x)}else{(x).wrapping_sub(k)})).wrapping_add(seed)).collect();let mut a=0u32;for x in mapped{a=a.wrapping_add(x);}let negative:Vec<u32>=xs.iter().copied().filter(|&x|!(x>seed)).collect();let mapped:Vec<u32>=negative.iter().map(|&x|((if (x<k){(k).wrapping_sub(x)}else{(x).wrapping_sub(k)})).wrapping_add(seed)).collect();let mut b=0u32;for x in mapped{b=b.wrapping_add(x);}*out=a.wrapping_mul(k).wrapping_add(b.wrapping_mul(3));1},
6=>{let left:Vec<u32>=xs.iter().map(|&x|(if (x<seed){x}else{k})).collect();let right:Vec<u32>=xs.iter().map(|&x|(if (x<seed){k}else{x})).collect();for(i,(&a,&b))in left.iter().zip(right.iter()).enumerate(){*out.add(i)=(if (a<b){(a).wrapping_add((b).wrapping_mul(k))}else{(a).wrapping_sub((b).wrapping_mul(k))});}xs.len()},
7=>{let left:Vec<u32>=xs.iter().map(|&x|(if (x>k){x}else{seed})).collect();let right:Vec<u32>=xs.iter().map(|&x|(if (x>k){seed}else{x})).collect();for(i,(&a,&b))in left.iter().zip(right.iter()).enumerate(){*out.add(i)=(if (a>b){((a).wrapping_mul(b)).wrapping_add(seed)}else{(a).wrapping_add((b).wrapping_mul(k))});}xs.len()},
_=>panic!("unknown case")}}
